window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c04c62ce42f8d2d3"]={"versions": [{"id": "FIG-c04c62ce42f8d2d3", "releases": ["R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Ausschnitt bzw. Metamodell-Beispiel) im Kontext der AUTOSAR XML Schema Production Rules (TPS_XMLSchemaProductionRules). Das Diagramm illustriert die Modellierung eines benutzerdefinierten primitiven Datentyps (<code>custom simple type</code>) im AUTOSAR-UML-Metamodell zur schemaweiten Ableitung von XML-Schema-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein einzelnes UML-Klassenelement:</p>\n<ul class=\"fig-list\">\n<li>Stereotyp: <code>«primitive»</code></li>\n<li>Bezeichner: <code>PositiveInteger</code></li>\n<li>Attribut-/Tag-Bereich (<code>tags</code>):</li>\n<li><code>xml.xsd.customType = POSITIVE-INTEGER</code></li>\n<li><code>xml.xsd.pattern = [1-9][0-9]<em>|0x[0-9a-f]</em>|0[0-7]<em>|0b[0-1]</em></code></li>\n<li><code>xml.xsd.type = string</code></li>\n</ul>\n<p class=\"fig-p\">Es sind keine Assoziationen, Vererbungsbeziehungen oder externen Schnittstellen abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Nachrichtenaustausche. Es definiert die statische Vorlage für den modellbasierten Codegenerator bzw. Schemagenerator (Generierungszeitpunkt).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Definitionsmuster gemäß Regel TPS_GST_00166:</p>\n<ul class=\"fig-list\">\n<li>Eine Klasse mit dem Stereotyp <code>«primitive»</code> und gesetztem Tag <code>xml.xsd.customType</code> bewirkt im XML-Schema die Erzeugung von zwei Schema-Konstrukten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Ein <code>xsd:simpleType</code> mit dem Suffix <code>--SIMPLE</code> (hier <code>POSITIVE-INTEGER--SIMPLE</code>), basierend auf dem Typ aus <code>xml.xsd.type</code> (<code>xsd:string</code>) und eingeschränkt durch das reguläre Muster in <code>xml.xsd.pattern</code> (unterstützt dezimale, hexadezimale, oktale und binäre Literale).</li>\n<li>Ein <code>xsd:complexType</code> mit Simple Content (hier <code>POSITIVE-INTEGER</code>), der das erzeugte Simple-Type-Element erweitert und um die Attributgruppe <code>AR:AR-OBJECT</code> ergänzt.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werkzeughersteller und Schemageneratoren müssen die Tagged Values exakt für die Pattern-Restriktion und Typableitung im generierten XSD auswerten.</li>\n</ul>"}, {"id": "FIG-dd1d1fe68f483b82", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Ausschnitt bzw. Metamodell-Beispiel) im Kontext der AUTOSAR XML Schema Production Rules (TPS_XMLSchemaProductionRules). Das Diagramm illustriert die Modellierung eines benutzerdefinierten primitiven Datentyps (<code>custom simple type</code>) im AUTOSAR-UML-Metamodell zur schemaweiten Ableitung von XML-Schema-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein einzelnes UML-Klassenelement:</p>\n<ul class=\"fig-list\">\n<li>Stereotyp: <code>«primitive»</code></li>\n<li>Bezeichner: <code>PositiveInteger</code></li>\n<li>Attribut-/Tag-Bereich (<code>tags</code>):</li>\n<li><code>xml.xsd.customType = POSITIVE-INTEGER</code></li>\n<li><code>xml.xsd.pattern = [1-9][0-9]<em>|0x[0-9a-f]</em>|0[0-7]<em>|0b[0-1]</em></code></li>\n<li><code>xml.xsd.type = string</code></li>\n</ul>\n<p class=\"fig-p\">Es sind keine Assoziationen, Vererbungsbeziehungen oder externen Schnittstellen abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Nachrichtenaustausche. Es definiert die statische Vorlage für den modellbasierten Codegenerator bzw. Schemagenerator (Generierungszeitpunkt).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Definitionsmuster gemäß Regel TPS_GST_00166:</p>\n<ul class=\"fig-list\">\n<li>Eine Klasse mit dem Stereotyp <code>«primitive»</code> und gesetztem Tag <code>xml.xsd.customType</code> bewirkt im XML-Schema die Erzeugung von zwei Schema-Konstrukten:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Ein <code>xsd:simpleType</code> mit dem Suffix <code>--SIMPLE</code> (hier <code>POSITIVE-INTEGER--SIMPLE</code>), basierend auf dem Typ aus <code>xml.xsd.type</code> (<code>xsd:string</code>) und eingeschränkt durch das reguläre Muster in <code>xml.xsd.pattern</code> (unterstützt dezimale, hexadezimale, oktale und binäre Literale).</li>\n<li>Ein <code>xsd:complexType</code> mit Simple Content (hier <code>POSITIVE-INTEGER</code>), der das erzeugte Simple-Type-Element erweitert und um die Attributgruppe <code>AR:AR-OBJECT</code> ergänzt.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werkzeughersteller und Schemageneratoren müssen die Tagged Values exakt für die Pattern-Restriktion und Typableitung im generierten XSD auswerten.</li>\n</ul>"}], "trans": [{"from": "FIG-c04c62ce42f8d2d3", "to": "FIG-dd1d1fe68f483b82", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dd1d1fe68f483b82", "to": "FIG-c04c62ce42f8d2d3", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
